fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut flash: i32 = host::display::state_get(1);
    let mut which: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let mut pad: i32 = 0;
        if px >= w / 2 { pad = pad + 1; }
        if py >= h / 2 { pad = pad + 2; }
        if pad == 0 { host::audio::tone(60, 180, 0); }
        if pad == 1 { host::audio::noise(120); }
        if pad == 2 { host::audio::noise(30); }
        if pad == 3 { host::audio::tone(800, 90, 1); }
        flash = 5;
        which = pad;
    }
    if flash > 0 { flash = flash - 1; }
    host::display::state_set(0, down);
    host::display::state_set(1, flash);
    host::display::state_set(2, which);
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 4 {
        let x: i32 = (i % 2) * (w / 2);
        let y: i32 = (i / 2) * (h / 2);
        let mut c: i32 = 0x1c1c24;
        if flash > 0 && i == which { c = 0xffffff; }
        host::display::fill_rect(x + 6, y + 6, w / 2 - 12, h / 2 - 12, c);
        i = i + 1;
    }
    host::display::draw_string(24, 24, "KICK", 0x00ff88, 2);
    host::display::draw_string(w / 2 + 24, 24, "SNARE", 0x00ff88, 2);
    host::display::draw_string(24, h / 2 + 24, "HAT", 0x00ff88, 2);
    host::display::draw_string(w / 2 + 24, h / 2 + 24, "COWBELL", 0x00ff88, 2);
    host::display::present();
}
